    ]
  },
  {
    "alert_id": "P004_PLAN_GAP_001",
    "title": "Clinician plan lacks action for reported symptom",
    "message": "The clinician's assessment and plan today only restates the patient's complaint of abdominal pain without any diagnostic workup, treatment, monitoring orders, or follow-up instructions. Guidelines require that every encounter includes active screening for suspected adverse drug reactions and that identified symptoms are acted upon and documented. The patient's viral load of 25 copies/mL confirms virological suppression, so regimen failure is unlikely to explain the symptom. The absence of any planned action for a new symptom in a stable patient represents a care gap that should be addressed at this visit.",
    "issue_type": "plan_review",
    "severity": "moderate",
    "recommended_action": "Document a differential diagnosis and management plan for the abdominal pain, including any indicated investigations, symptom-directed treatment, and a defined follow-up interval.",
